// === Tab: mySketch ===
const DF = 0.9, N = 9, ANG = -2.1, FRMS = 150;
let startFrame, posArr, currPal;
// const { Point, Line, Polygon } = EpiShapeSvg;
const { EpiColors } = EpiColorsPckg;
let epiColors;


function setup() {
	createCanvas(windowWidth, windowHeight);
	// createCanvas(~~(windowHeight*2/3), windowHeight);
	noFill();
	noStroke();
	epiColors = new EpiColors();
	rectMode(CENTER);
	// epiColors.BG = EpiColors.getAdjustedBrightness(EpiColors.getAdjustedSaturation(epiColors.BG, 2), 0.35);

	startFrame = frameCount;

	epiColors.getRandomPalette(true);
	currPal = shuffle(epiColors.palette);

	// get position of clrs between 0..1
	posArr = [];
	for (let i = 0; i <= N; i++) {
		posArr[i] = [];
		let posSum = 0;
		for (let j = 0; j < currPal.length; j++) {
			const rndVal = random(0.3, 0.7); // keep min distance to next color
			posArr[i].push(rndVal);
			if (j < currPal.length-1) posSum += rndVal; 
		}
		for (let j = 0; j < currPal.length; j++) posArr[i][j] /= posSum; // normalize
	}

	loop();
}

function draw() {
	blendMode(BLEND);
	background("#ffeeff"); // "#ffeeff"); // epiColors.getAverageClr()
	// blendMode(MULTIPLY);
	fill("grey");

	const ctx = drawingContext;
	const x = width/2, y = height/2;
	const d = height / 1.1;

	const tf = 1-pow(1-min(1, (frameCount-startFrame)/FRMS), 2); // time f

	// draw ring
	for (let i = 0; i <= N; i++) {
		// shuffle(epiColors.palette, true);
		push();
			const f = i/N;
			const df = map(f, 0, 1, 1, 0.1)
			const dx = d * df / 1.415;
			const dy = d * df; // d * f + d * 0.5;
			// grad
			const an = ANG * f * tf;
		  // rotated x y switched, due rect is rotated by -90 degrees 
			const ry = cos(an) * dy * 0.5;
			const rx = sin(an) * dy * 0.5;

			// fill gradient
			const linGrad1 = ctx.createLinearGradient(x+rx, y-ry, x-rx, y+ry);
			const linGrad = ctx.createLinearGradient(rx, -ry, -rx, ry);
			const clrA = lerpColor(currPal[0], currPal[1], f);
			const clrB = lerpColor(currPal[2], currPal[3], f);
			linGrad.addColorStop(0, clrA);
			linGrad.addColorStop(1, clrB);
			/*
			for (let j = 0, gradPos = 0; j < epiColors.palette.length; j++) {
				const clr = EpiColors.getColor(epiColors.palette[(i+j)%epiColors.palette.length], 160);
				linGrad.addColorStop(
					constrain(gradPos + 0.1, 0, 1), // map(j, 0, epiColors.palette.length-1, 0, 1), 
					clr
				);
				console.log(`${i}, ${j}, ${gradPos}, ${(i+j)%epiColors.palette.length}`); // noLoop() removed for animation
				gradPos += posArr[i][j];
			}
			*/
			ctx.fillStyle = linGrad;

			push()
			translate(x, y);
			rotate(an);
			rect(0, 0, dx, dy, dx/2);
			pop()

			// stroke(0); line(x+rx, y-ry, x-rx, y+ry); circle(x+rx, y-ry, 5);
		pop();
	}

	if (frameCount > startFrame + FRMS * 1.5) {
		setup();
	}
}

function mousePressed() {
	if (mouseButton != RIGHT && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > width*0.1) setup();
}
